(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["principles-of-diagnostic-medicine-i-exam-1-urinalysis-quiz-version-2"]={"title":"Urinalysis Quiz 2 — PDM I Exam 1","category":"Principles of Diagnostic Medicine I","exam":"Exam 1","sem":"fall-2026","questions":[{"q":"A patient with sweet-smelling urine has ketones and glucose on the dipstick. Which picture does that fit?","choices":["A simple urinary tract infection","Uncontrolled diabetes mellitus","Rhabdomyolysis","Biliary obstruction"],"answer":1,"exp":"Correct — glucose spilling with ketones from fatty acid metabolism. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 9"},{"q":"A dipstick supports a urinary tract infection. What identifies the organism and what will treat it?","choices":["Urine culture and sensitivity","Gram stain of the urine alone","A repeat dipstick after treatment","Blood cultures"],"answer":0,"exp":"Correct — culture names the organism and sensitivity picks the agent. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 34"},{"q":"What does the blood pad on a reagent strip actually detect?","choices":["Heme","Intact red cells only","Free hemoglobin only","Iron released from ferritin stores"],"answer":0,"exp":"Correct — and heme is present in all three of the possible sources. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 23"},{"q":"A specimen collected two hours ago smells strongly of ammonia. What explains it?","choices":["There is a connection between bowel and bladder","The patient is in ketoacidosis","Bacteria broke down the urea as it stood","The sample has been refrigerated"],"answer":2,"exp":"Correct — standing lets bacteria decompose the urea. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 9"},{"q":"Bence Jones proteins are suspected. Which test identifies them?","choices":["A reagent strip read by an automated reader","Urine protein electrophoresis","Urine culture and sensitivity","Microscopic examination of the sediment"],"answer":1,"exp":"Correct — electrophoresis is what finds them. — Lecture recording, 1 September 2026, 40:09"},{"q":"Bilirubin is found in the urine. Where does the problem lie?","choices":["In the concentrating ability of the kidney","Before conjugation, in the breakdown of red cells","In the renal tubules' handling of protein","After conjugation in the liver, or in the biliary tract"],"answer":3,"exp":"Correct — bilirubinuria points downstream of conjugation. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 27"},{"q":"Which form of bilirubin appears in urine, and why?","choices":["Both forms equally","Unconjugated, because it is bound to albumin","Conjugated, because it is water soluble","Neither, since bilirubin is cleared entirely in bile"],"answer":2,"exp":"Correct — only the conjugated form dissolves in urine. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 27"},{"q":"What does specific gravity measure?","choices":["The osmotic pressure the urine exerts","The number of particles per litre of urine","Solute weight against an equal volume of water","The volume of urine produced per hour"],"answer":2,"exp":"Correct — it is a ratio of weights. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 31"},{"q":"Urine is yellow-brown with a green tinge. Which substance does that point to?","choices":["Bilirubin","Hemoglobin","Myoglobin","Urea"],"answer":0,"exp":"Correct — a yellow-brown or green colour points to bilirubin. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 7"},{"q":"A patient with ketonuria has a normal blood glucose and reports not eating for two days. What explains the ketones?","choices":["Overhydration","Uncontrolled diabetes mellitus","A urinary tract infection","Starvation"],"answer":3,"exp":"Correct — fasting drives fatty acid metabolism just as insulin deficiency does. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 21"},{"q":"Why must the timing of a reagent strip reading be watched closely?","choices":["All pads must be read at exactly sixty seconds","Each analyte has its own reading time","The strip must be read before it touches the urine","Reading time only matters for the pH pad"],"answer":1,"exp":"Correct — the times differ from one pad to the next. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 36 (image)"},{"q":"Which protein does the dipstick mainly detect, and what does it report on?","choices":["Albumin, reflecting glomerular and tubular function","Immunoglobulin, reporting on immune activity","Hemoglobin, reporting on red cell breakdown","Myoglobin, reporting on muscle injury"],"answer":0,"exp":"Correct — albumin is the protein, and both are what it reflects. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 28"},{"q":"A patient with a longstanding indwelling catheter has bacteria in the urine but no symptoms. What does that most likely represent?","choices":["Interstitial cystitis","Acute pyelonephritis","Contamination from the vagina","Catheter colonisation"],"answer":3,"exp":"Correct — long-term catheters are colonised. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 34"},{"q":"Which serum finding supports myoglobinuria?","choices":["A raised conjugated bilirubin","A raised unconjugated bilirubin","A raised creatine phosphokinase","A raised serum glucose"],"answer":2,"exp":"Correct — it is released alongside myoglobin from damaged muscle. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 26"},{"q":"Besides urinary tract infection, which conditions can turn the leukocyte esterase positive?","choices":["Diabetes insipidus and severe dehydration","Interstitial cystitis and glomerulonephritis","Rhabdomyolysis and muscle injury","Multiple myeloma and amyloidosis"],"answer":1,"exp":"Correct — both are inflammatory and can produce pyuria. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 19"},{"q":"The blood pad is positive. What can it NOT tell you?","choices":["Whether the specimen was fresh","Whether heme is present at all","Which source is responsible","Whether protein is also present"],"answer":2,"exp":"Correct — the pad does not differentiate between them. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 23"},{"q":"Urine is noted to be foamy. Which finding does that suggest?","choices":["Bilirubinuria","Glucosuria","Ketonuria","Proteinuria"],"answer":3,"exp":"Correct — foam is associated with protein in the urine. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 8"},{"q":"A woman with dysuria and frequency has a dipstick positive for leukocyte esterase, nitrites, and blood, with glucose, bilirubin, ketones, and protein all negative. How is this read?","choices":["It fits nephrotic syndrome","It fits diabetic ketoacidosis","It fits a urinary tract infection","It fits biliary obstruction"],"answer":2,"exp":"Correct — pyuria with nitrites and blood, and nothing pointing elsewhere. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 36 (marks resolved by position)"},{"q":"Which of these produces hemoglobinuria?","choices":["A hemolytic transfusion reaction","A crush injury to the thigh","A bladder tumour","A ureteric stone"],"answer":0,"exp":"Correct — rapid intravascular destruction of red cells. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 25"},{"q":"An older patient has bone pain, anemia, and a raised total protein, but the urine dipstick protein is negative. What should be done?","choices":["Repeat the dipstick on a first-morning specimen","Accept the negative pad as excluding urinary protein loss","Send urine protein electrophoresis","Send a urine culture and sensitivity"],"answer":2,"exp":"Correct — a negative pad does not exclude light chains. — Lecture recording, 1 September 2026, 40:09"},{"q":"How many red cells define microscopic hematuria?","choices":["One or more","Three or more","Ten or more","Twenty or more"],"answer":1,"exp":"Correct — that is the threshold. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 23 (image)"},{"q":"How does free hemoglobin reach the urine?","choices":["Through failure of tubular reabsorption of protein","Through bleeding anywhere along the urinary tract","Through release from injured skeletal muscle","Through intravascular destruction of red cells"],"answer":3,"exp":"Correct — hemolysis inside the vessels releases it. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 25"},{"q":"Which two structures make up a nephron?","choices":["A calyx and a collecting duct","A glomerulus and a tubule","A renal artery and a renal vein","A cortex and a medulla"],"answer":1,"exp":"Correct — those two together form the nephron. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 15"},{"q":"A toddler is being assessed for a urinary tract infection and the nitrite pad is negative. What limits that result here?","choices":["Children void too often for the conversion","The pad cannot be used under the age of five","Children produce no urinary nitrates","Paediatric specimens must be refrigerated first"],"answer":0,"exp":"Correct — the conversion needs urine to sit in the bladder. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 20"},{"q":"Persistent proteinuria is best understood as what?","choices":["Proof of nephrotic syndrome","A normal variant in most adults","A significant sign of renal disease","Evidence of urinary tract infection"],"answer":2,"exp":"Correct — persistence is what makes it significant. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 29"},{"q":"Why does a negative nitrite result fail to exclude a urinary tract infection?","choices":["The pad cannot detect nitrites below body temperature","The pad only works on a first-morning specimen","Nitrites are destroyed by refrigeration","Escherichia coli is rarely urease-positive"],"answer":3,"exp":"Correct — the commonest organism does not turn the pad positive. — Lecture recording, 1 September 2026, 24:06"},{"q":"In a patient with cystitis, which negative dipstick results help to rule other things out?","choices":["Glucose, ketones, bilirubin, and protein","Specific gravity, pH, and appearance","Leukocyte esterase and nitrites","Blood and leukocyte esterase"],"answer":0,"exp":"Correct — their absence points away from metabolic, hepatic, and glomerular causes. — Lecture recording, 1 September 2026, 49:21"},{"q":"Why is bilirubinuria valuable as a screening finding?","choices":["It can precede visible jaundice by days","It confirms the cause of the liver disease","It distinguishes hepatitis from cirrhosis","It rules out biliary obstruction"],"answer":0,"exp":"Correct — it can precede visible jaundice. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 27"},{"q":"Which analyte on a urinalysis is reported as a value rather than as positive or negative?","choices":["Nitrites","Specific gravity","Leukocyte esterase","Bilirubin"],"answer":1,"exp":"Correct — it is a ratio, so it always carries a number. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 14"},{"q":"How long must urine sit in the bladder between voids for nitrites to be detectable?","choices":["About thirty minutes","More than four hours","About one hour","A full twenty-four hours"],"answer":1,"exp":"Correct — the conversion needs that long. — 6. Urinalysis Diagnostics SV Gopal Fall 2026.pptx, Slide 20"}]};
